import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.Kw_SGbqu.js";const u=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{"title":"隐私政策","search":false},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),n={name:"privacy/index.md"};function l(o,a,h,p,s,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p><strong>草案，正式文本待发布。</strong> 本页说明 FurinaChronicle 的本地数据处理原则，以及可选功能启用后的数据处理方式。云服务、全服统计和诊断功能的说明属于规划，适用于未来实际提供相应功能的版本。</p><h2 id="默认在本地处理数据" tabindex="-1">默认在本地处理数据 <a class="header-anchor" href="#默认在本地处理数据" aria-label="Permalink to &quot;默认在本地处理数据&quot;">​</a></h2><p>FurinaChronicle 默认在你的设备上处理并保存游戏历程、抽卡、角色养成、挑战记录和档案设置。我们不会主动收集这些数据或将它们上传到 FurinaChronicle 的服务器。查看、统计和导出本地档案无需 Furina 云账号。</p><h2 id="furina-云服务" tabindex="-1">Furina 云服务 <a class="header-anchor" href="#furina-云服务" aria-label="Permalink to &quot;Furina 云服务&quot;">​</a></h2><p>登录 Furina 云账号后，只有当你主动选择上传并确认后，应用才会将所选数据发送到 FurinaChronicle 云端。上传前会展示数据范围，具体包含的记录以对应功能的说明及本次上传内容为准。</p><ul><li><strong>上传档案内的一个账号</strong>。只上传所选账号在该档案中的数据。恢复时，你可以选择任意目标档案，预览并确认与其中同一游戏、区服和 UID 的账号合并或覆盖，也可以在没有匹配账号时新增账号。其他档案中的同 UID 副本仍独立保存。</li><li><strong>上传一个完整档案</strong>。上传档案、其中受支持的账号及记录，以及该档案受支持的修改历史。上传前会说明所包含的历史类型。当前 Archive 格式可保存受支持的记录修订，源设备的撤销材料和完整操作历史有单独的格式边界。</li></ul><p>游戏通行证凭据不随以上两种上传传输。</p><h2 id="全服统计投稿" tabindex="-1">全服统计投稿 <a class="header-anchor" href="#全服统计投稿" aria-label="Permalink to &quot;全服统计投稿&quot;">​</a></h2><p>使用某项全服统计功能时，页面会显示本次将提交的数据范围及其统计用途，并提供「上传数据参与统计」按钮。点击该按钮即表示你同意上传所展示的数据，并允许 FurinaChronicle 将本次提交用于该项全服统计。</p><p>你可以只查看全服统计结果。每次投稿独立发起，授权范围限于该次提交。云备份与全服统计投稿独立处理，云备份数据不会自动纳入统计。</p><h2 id="用户主动使用的第三方服务" tabindex="-1">用户主动使用的第三方服务 <a class="header-anchor" href="#用户主动使用的第三方服务" aria-label="Permalink to &quot;用户主动使用的第三方服务&quot;">​</a></h2><p>我们不会主动向第三方提供你的档案、账号记录或诊断数据。只有你主动使用需要连接第三方的功能时，应用才会向对应服务发送完成操作所需的信息。以下是现有的连接场景。</p><ul><li>使用米游社或 HoYoLAB 登录和刷新时，应用会向对应的官方服务发送登录、验证或查询所需的信息。</li><li>从「提瓦特小助手」导入时，应用会在发送前说明接收方和数据范围。经你确认后，应用向提瓦特小助手发送游戏 UID 与临时抽卡链接。</li><li>登录过程中的人机验证由第三方验证服务在应用内的页面中完成。该页面脚本由验证服务方提供，验证服务方可能收到你的网络地址和浏览器标识。</li><li>为了显示卡池、物品名称与图标，应用会从公开元数据来源和图片地址发起只读请求，包括官方计算器接口、提瓦特小助手公开的卡池数据、Snap.Metadata 公开元数据以及图标图片地址。这些请求不包含你的游戏记录或游戏通行证凭据。</li></ul><p>以上连接均在你主动触发相应功能时发生。应用不会在后台向你未使用的第三方服务发送数据。</p><p>游戏通行证凭据保存在设备的安全存储中。普通档案备份不包含这些凭据。</p><h2 id="应用使用统计和错误诊断" tabindex="-1">应用使用统计和错误诊断 <a class="header-anchor" href="#应用使用统计和错误诊断" aria-label="Permalink to &quot;应用使用统计和错误诊断&quot;">​</a></h2><p>当前版本的诊断信息只写入本机的日志文件，导出诊断报告时由你选择保存位置，应用不会自动发送。应用内已对日志中的凭据、链接参数和本机绝对路径做脱敏处理。</p><p>计划在提供诊断上报功能的版本中默认开启使用统计和错误诊断。首次发送前，应用会说明发送的内容、用途和关闭方式，并在适用时取得必要授权。你可以在应用设置中关闭此功能，停止后续发送。</p><p>诊断数据可能包括应用活跃及功能使用事件、错误报告，以及由应用生成、用于事件去重和问题诊断的设备标识。这些信息仅用于开发、排查错误及改进应用的性能与使用体验。诊断数据通过本项目接收，与游戏档案分开处理。</p><p>应用在发送前去除非必要的直接标识，汇总结果按匿名化要求处理。可以持续区分同一设备的应用标识按去标识化信息处理。诊断数据不包含游戏通行证凭据、游戏 UID、临时抽卡链接或游戏档案内容。</p><h2 id="管理本地数据" tabindex="-1">管理本地数据 <a class="header-anchor" href="#管理本地数据" aria-label="Permalink to &quot;管理本地数据&quot;">​</a></h2><p>你可以通过应用查看、导出或删除本地档案。你另存的导出文件、其他设备上的副本及云端备份，可在各自位置管理。具体操作见<a href="./../guide/archive.html">备份与迁移</a>。</p><p>正式发布时，本页将补充发布主体、联系渠道、各类数据的保存期限及适用版本。</p>',24)])])}const _=e(n,[["render",l]]);export{u as __pageData,_ as default};
